mkdir -p "C:/Users/ASUS/AppData/Local/Temp/claude/D--Work-Freelance-sellervate-project/0181ff62-0ce2-429e-afd7-46a4a4b2942d/scratchpad" && cat > "C:/Users/ASUS/AppData/Local/Temp/claude/D--Work-Freelance-sellervate-project/0181ff62-0ce2-429e-afd7-46a4a4b2942d/scratchpad/export.cjs" <<'EOF'
const fs = require('fs');
const [src, outBase, title] = process.argv.slice(2);
const EMAIL = '<redacted>';
const esc = EMAIL.replace(/[.]/g, '\\\\.');
const redact = s => s.split(EMAIL).join('<redacted>').split(EMAIL.replace(/\./g, '\\.')).join('<redacted>').split(EMAIL.replace(/\./g, '\\\\.')).join('<redacted>');
const raw = fs.readFileSync(src, 'utf8');
fs.writeFileSync(outBase + '.jsonl', redact(raw));
const lines = raw.trim().split('\n').map(l => JSON.parse(l));
let md = `# Transcript de sesión — ${title}\n\nExportado desde Claude Code. Mensajes del usuario y del asistente completos; las llamadas a herramientas aparecen resumidas en una línea y sus resultados se omiten. El log crudo está en el \`.jsonl\` de al lado.\n\n`;
for (const x of lines) {
  if (x.isSidechain) continue;
  if (x.type === 'user' && !x.isMeta) {
    const c = x.message.content;
    const texts = typeof c === 'string' ? [c] : c.filter(b => b.type === 'text').map(b => b.text);
    const t = texts.join('\n').replace(/<system-reminder>[\s\S]*?<\/system-reminder>/g, '').trim();
    if (t && !t.startsWith('<')) md += `\n---\n\n## 🧑 Usuario\n\n${t}\n\n`;
    if (typeof c !== 'string' && c.some(b => b.type === 'image')) md += `_(captura de pantalla adjunta)_\n\n`;
  } else if (x.type === 'assistant') {
    for (const b of x.message.content || []) {
      if (b.type === 'text' && b.text.trim()) md += `\n### 🤖 Asistente\n\n${b.text.trim()}\n\n`;
      else if (b.type === 'tool_use') md += `> 🔧 \`${b.name}\`${b.input && b.input.description ? ' — ' + b.input.description : ''}\n\n`;
    }
  }
}
fs.writeFileSync(outBase + '.md', redact(md));
const leftover = (redact(raw) + md).includes(EMAIL) ? 'EMAIL STILL PRESENT' : 'clean';
console.log('lines', lines.length, 'md bytes', md.length, leftover);
EOF
